) AS (
  VALUES 
    (206::BIGINT, 'Califica un toque duro, asistencia full obligatoria, hace mucha práctica y siempre es en parejas, deja muchos quices. No es tan mala ni tan buena, si no tiene más opción está ok.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos exámenes']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'b55650235d8bb3486d543ce6cf35d7929db93610fdf1492fb1bb1d3a4c53db90'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Muy linda persona, de verdad le interesa que la gente pase pero explica todo MUY rápido y habla bajito. Hace mucha práctica en clase, casi que el 95% de clases es hacer práctica. Sirve para la gente que procrastina llegar a practicar a la casa pero vaya a consulta para entender mejor los temas'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases largas']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e9ec25d1f9dcbc1267cb1c098e01a5b236804c1b1a36f790551c91d50847b850'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Puede que al inicio cueste entenderle pero, se preocupa mucho por los estudiantes, y busca formas de siempre ayudar a subir la nota. Ayuda mucho ir a consulta para poder entender mejor los temas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b7860505bf1190386a30580c13a9e02859a92e81e044536d07b7d5c8a50a624e'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Muy buena profesora en sus clases explica bien y si uno tiene que preguntar 5 veces para entender ella explica las 5 veces, los quices los hace todos en pareja y en general califica suave, aparte de que se aprende mucho ya que enseña dando ejemplos mas que solo formulas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '9d5c0c5e0e0ca86abd91dfcaa04fb46ab1394bd4a9ac445b16f80a62b146dd8c'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Es de lo mejor que tiene la escuela de física, hace quices en pareja y hace bastante práctica en clase. Califica bastante suave y atiende todas las dudas que a uno le surjan. No usa presentaciones entonces hay que escribir todo lo que anota en la pizarra.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-11T00:00:00+00:00'::TIMESTAMPTZ, '2db1ee5b7fdca89d006a12ec8e8b4f26b8adc56494cd60045a21a91bd53e6b32'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Para el lab de fisica 1 es muy buena nota, califica normal aunque si tarda un poco pero si usted ocupa ayuda ella le vuelve a explicar y le ayuda mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '77185bca4b958721c090e2d27fdcbc22243f8711319496be65695ad7cb6050c8'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Es buena docente. Se puede preguntar con confianza, da buenas explicaciones.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, '41356394bbd27abed9df7602854569df020e8df911de646f35f61612816591fa'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Este año volvió al TEC luego de estudiar en el extranjero. Superbuena persona, por la naturaleza del curso toca estudiar antes de clase, pero de todas formas ella está siempre dispuesta a explicar si no estudiaste o si tienes dudas. No califica tan rudo el primer informe, pero el resto sí. Usó GAAP.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-06-24T00:00:00+00:00'::TIMESTAMPTZ, '7f75b1ee5acc284eae7f17bfdd7141d05aee3b09e6db8de1035713466485c5e4'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Súper linda persona. No explica tanto antes de hacer los trabajos entonces hay que ver los videos de la cátedra antes, igual siempre ayuda. Hizo los cuestionarios en el GAAP y pasó lista como dos veces. Intenten conseguir un buen grupo o matricular con amigos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '82d243da3a472a58ed4be6b9c831132673fcd00c35faf67443ca2075d6a56a0d'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Súper desordenada. No lleva registros de nada. Lo hace llevar bitácora a mano. Pero es fácil pasar.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-16T00:00:00+00:00'::TIMESTAMPTZ, 'ea6dda5aecea91b8b632822171c73d45cf406f7e205d0f12771af788cce08df8'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Es muy buena gente y ayuda hasta que uno entienda'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8e17cfab8f6c7b950a69e0eb15581aa9d2178b262456499a967094c98bf1c017'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'Muy buena profesora. Explica muy claro y se hace mucha práctica. Califica suave y los quices suelen ser en pareja. La clase se pasa rápido y no la hace aburrida.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'ae3878060b498d90d4fee798e22badb8bc646cc23d0546b0a06b9869ed90cb4d'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'La mejor, una completa profesional, admirable.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c483696f4021a0208d1d52193c731622729264bbf47de0de7d4d56ab38aba67f'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Buena profe, algo aburrida la clase eso si.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '42093980a62562337492fdcd9706ed722ee552170d43ee44f5e2c96fbbee1914'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Es buena gente. Ayuda a la gente que muestra interés, quices fáciles y siempre aclara las dudas. Además hace bastante práctica. En general, la recomiendo, pero mejor no lleve con ella si tiene muy malas bases en física'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'ac8563ad14878acec4aaf00c04c672a19da5483544505ad91a2fb5d25fbbb925'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Pone mucha practica, no hace casi quices y solo tres tareas. Si va a llevar fisica por primera vez no la lleve con ella porque no explica casi teoria pero muy recomendada si va a repetir fisica porque hace mucha practica'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '82ddef6562347ed11bf25d8fb1d8be5d0510a7a7a5f4d8fafd74ff8a7b7e0829'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Excelente profesora. Califica super suave, instrucciones muy claras a la hora de realizar los experimentos. Muy divertida y buena gente. El segundo examen es una práctica muy sencilla. La recomiendo totalmente.!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'acc6807f303689ca48a4ca55f42d789a89d69a8dd5d6804bd104c366e15f8c9b'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'Es muy buena gente y es muy fácil pasar con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, '34fc48dd04eac9aec059413e18b10c2f58975bd8f7ae0c63a9868a089bd8db97'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'Excelente, se interesa por que uno aprenda y no califica duro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e39516a32354906de14ea2b43f0c056eb72ee4acaf5a06547288db1781afed99'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'Explica super claro, uno entiende muy facil yalifica suave'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '8e89c576be490f836455c4ba49ed8132bcb246677c509bd5697441a6911f2374'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'No es aburrida como dicen, pero no es la mejor profe para alguien que le cuesta física. En comparación de otros profes es buena, califica suave, quices fáciles, genera confianza para preguntarle cosas...'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-03T00:00:00+00:00'::TIMESTAMPTZ, '40dd624b99ff32693f658b73ca581ab5b6becc5e11f914c07b0bf3c204c09fb8'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Explica bien, los quices se parecen a lo visto en clase, califica normal, no regala pero tampoco quita. La clases esta llena de ejercicios de principio a fin. Pone a hacer tareas, quices y demás trabajo en clase en parejas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'c12c5ee85281a7926fda7a2cc80f5e0a115ac9bc35d654196c0e10538183ce00'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Seguramente no es la mejor.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-29T00:00:00+00:00'::TIMESTAMPTZ, '5c433c080ff5541a0dd37deea3f45d3852517c1c2bac8f5d41e8ca8436a88b30'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Tuve que asistir de oyente con otra profe porque con ella me dormía'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-27T00:00:00+00:00'::TIMESTAMPTZ, '58083b209dfe3e94ed455ac5f7a3c2eef31bb36d937710c1f942718b27916045'::TEXT, ARRAY[604]::BIGINT[]),
