    (206::BIGINT, 'No se le entiende muy bien cundo explica, hay que ser autodidacta con ella, las clases se hacen eternas más después de almuerzo, apenas para dormir!'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '6fa44278777181a06982ca823d1288055854e008ef3334208078db86ef759a0b'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Muy mala profesora. NO me quizo ayudar con medio punto'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-17T00:00:00+00:00'::TIMESTAMPTZ, '72af557a05333fd5f89767e16ac8ace4f3935eda9c595968e3589175eaf3e8a6'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Muy buena profe, si tenés algún problema con tareas o algo así ella te da la oportunidad de que la entregués después o te ayuda de alguna manera. Explica bien, sin embargo, hay que poner de parte de uno también. Full recomendada'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-01T00:00:00+00:00'::TIMESTAMPTZ, 'cf52303a1bb27bf26b1f034ffa203720319a773a234d9188b4367bdedc7d50d9'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Profe muy pura vida. Hace el curso tan fácil que es imposible quedarse con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'ea81d06710d1bcc24e45293d9aff3405840698ffc042b3f3f3a8c3de0b638957'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Explica súper claro y rápido la materia de manera que al finalizar tema se hacen ejercicios en clase (en parejas) que luego son también revisados en clase. No deja todos lo ejercicios en las tareas de cátedra. Muy recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, '94dfc48a66b0d81ea94b162d3264367118f3f91f36a0cb731b7edef1a24d9227'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Excelente profesora, quices fáciles y ayuda bastante... Hay que elaborar cada semana marco teórico de la práctica y llevarle los informes, no califica muy rudo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'dd3ad4ede9c8bcd94f7c33eb5170a3254b3e4f7e87e09954796765b4f0e657d5'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'Hace la clase muy divertida. Es muy compresiva. Entrega los informes hasta la entrega de notas. Ayuda en la nota. Explica muy bien y se preocupa porque uno aprenda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '26d3ada73581b00ed3d32de00abb727e5a6a9017d9aacbb2daeae8553c42957f'::TEXT, ARRAY[631]::BIGINT[]),
    (206::BIGINT, 'El curso ni se siente, es fácil de pasar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-27T00:00:00+00:00'::TIMESTAMPTZ, '2f3850385331f9b22aa56ffa81a59e50090515e1a66befcd70a4fac1799b7a27'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Profesora muy neutral, se va a lo que se va, lo ayuda a uno cuando lo necesita eso sí.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-01T00:00:00+00:00'::TIMESTAMPTZ, '6f3df4a59c24e953f73e3f68ac98d271cb7d485aa8da8b86c868eac9dc132065'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'No pasa asistencia pero aveces hace quizzes de asistencia. Explica super bien y se hace un quiz despues de cada tema. Un monton de practica que ayuda para el examen. Las clases son muy esquematizadas. Si puede meter con ella no lo piense!'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-28T00:00:00+00:00'::TIMESTAMPTZ, '2704b0fed5c8e19f09a1fae45e5cf7d9c4d01e5b4b76b7e6f47d782d2bfa782f'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Las prácticas que se hacen son pocas y a veces las pide a mano, pero ella se toma el tiempo de explicar lo que hay que hacer. Las clases son entretenidas y le gusta que uno piense las soluciones.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '05493892e1393d9710f22dfc209e263bcb112657fa5839debabf7b5552238505'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Simplemente pase con un 80 sin darme cuenta de nada, literalmente no se absolutamente nada de lab y pase con un 80.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'd9b9942546ad6e63e7a7c66a8483b7bb8f8202223a78a7923a550c4b09032cb2'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '974158c023bcf03fc4af29accb7188151cc5684d01b4b875ed1324c8c49f6a44'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Los informes son a mano, es lo único malo. En consulta es super amable. Los quices son fáciles y la libreta es muy importante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2017-06-10T00:00:00+00:00'::TIMESTAMPTZ, '59ed74a214e50458c7d747d8467e1da4805922fbe94d1f88673569ecf9982b04'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'La profe es agradable, sin embargo es bastante irresponsable, llega tarde casi siempre y nunca esta en la oficina a las horas de consulta. Habla SÚPER bajito, sentarse al frente desde la primera clase es lo ideal. Quices fáciles, la mitad del curso es la libreta, si la tenés al día pasas fijo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'a04f3b0fc611261bc91f5c07ad96d9ac9bbf2986b9b24177c6995d4e819b56ed'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Las clases en serio son aburridisimas!!!! Pero con tener la libreta al día ya pasó el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-01-27T00:00:00+00:00'::TIMESTAMPTZ, '1bd1bdfe276d51e84283de4da0368240199365b945d5b37f5ea9825c32bbcdad'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'En mi experiencia basicamente lo que hcimos fue ejercicios en clases'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-13T00:00:00+00:00'::TIMESTAMPTZ, '25d5a8299a19b9a61e6514e7a0ee6ab0a40731966948de73a3c41f42b88bc2dd'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'La clase es aburrida, si se lleva la bitácora como ella la pide tiene los puntos asegurados. No es mala pero tampoco buena.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'f0ce4186761a1342ef0272e5f3ae85514e7de759a31e22f3e5e54f9c142739b1'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Los informes son muy matados porque hay que hacerlos a mano, pero califica justo y es muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '9e6777f310c1415780135e97593a447a336bba42b0a6443fa69fc0faab08b564'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Super sencillo,explica bien ,califica suave Pero todo es a mano ,y es muy matado hacerlo todo asi Es carismatica y se vacila con ella'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f64b029f7f805eab954858db5e7c35abdd6d62723f6badafec87bfc4b86a17f1'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-24T00:00:00+00:00'::TIMESTAMPTZ, '2d35432804a496b187a5a81a09836e6282610aa93222dff7bee60ab5bd9ad6d1'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Una profesora excelente. Califica con el corazón en la mano y por lo tanto, brinda apoyo a quienes de verdad le ponen. Con ella se hace una clase de teoría y varias de prácticas, por lo tanto, usted llega super afilado para los exámenes. Eso sí, hace varios quices. Excelente profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'ebc7ac63767a5c43396a725db1d9bfa0cf5f6f57048dfe2f082577fa3306559d'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'la clase es facil, pero los informes son muy matados, lo normal en comparacion a los demas labs, expeto que hay que hacerlos a mano. exelente persona, muy buena nota, con ella se vacila. deberia hacer mas quices. lo malo es que es muy desordena con las pacticas'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'f3481d811de28eeaf1e93dd9b025f734e5627edff1be0907733bf6a2e83c98a0'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Cualquiera que diga que ella es una vaga o que es mala profesora, es honestamente porque es un/a vago/a que no estudiaba y quería pasar a pura explicación. Como persona es una teja, hace muchos ejercicios y explica todos los casos posibles. Las clases son super entretenidas y es muy buena nota.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-10-13T00:00:00+00:00'::TIMESTAMPTZ, 'd7c52270e9b2c3c9a2cd3db835d76359a174b77f927248529d509a6e5b3c967f'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Buena persona y profe. Lo único malo es que hay que hacer informes y experiencias a mano. Califica bastante justo...Las clases son entretenidas.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '591abde3dc097c944c9a645d7ca4e20329624d932e4938749f0cc4d9a64957ed'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '76a300d51aeaa4a09f1d8714c2ce5c6da2feb8ce99717e45096256f930f991be'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f56249520d914e657f3dfa6c535feb62c8a1303a1240ecb7c5330c3bc98ce09c'::TEXT, ARRAY[3257]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2016-06-12T00:00:00+00:00'::TIMESTAMPTZ, '9f2e515e05295d50fbc6c18e7b322d6d1c6214354d95d4ae0f1af4ae59d1d49c'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Es claraa explicando pero estricta. Se fija en la asistencia y puntualidad.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'a1d7808d6685e36aeae9df2f3a212427ac81e6a275bd7e0d9ac615fc91a5abb3'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'c866724796c44e06def8fea2d9ceccd9ead90e95689ef87343c1af0b290602f2'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Explica mal, con pereza, los quices son mas o menos, califica justo. Y para lab NUNCA matriculen con ella, porque pone hacer a mano los informes y la libreta.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-12-16T00:00:00+00:00'::TIMESTAMPTZ, '12e1718fcf59b20d2037f7f1887f43921923a454d2aaa7da9f5fec25d4783213'::TEXT, ARRAY[604, 607]::BIGINT[]),
    (206::BIGINT, 'Excelente profesora, le gusta que los estudiantes aprendan. Es necesario ir con ganas de aprender, pero es lo mejor :D'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5b0ccf8b537fadc31426d099ba8227c91658df9d60d7e81200fb40ea9b3b157d'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b1f17ca8a6b6299799bb00fe5bc5e7b6177b70cf0152e64fdfdfa69655726366'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Recomendada! es una excelente profe, da practicas que son muy similares a los exámenes por lo que si pudo resolverlas, puede hacer el examen ademas califica suave, y es una teja como persona.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c38e707fe370f86ba27a019e39fca21a8542a44a464f610a5b58ddd56b361900'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'No es muy estricta con lo de las experiencias, con los informes sí. Es buena gente, y explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'de3b85e2658f0654465699b07f6c14a3968663b581c00d9bdf4fcf6c1866c7ac'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Lo que dice el Mae de abajo es paja...los resúmenes son malos y "para vagos" si no los complementa con el libro. Tal parece que solo leyó los resúmenes y lo sonaron...los resúmenes son buenos pero no lo único que debe estudiar. A la profe le gusta que vayan a consulta porque en clase es muy rapida.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-22T00:00:00+00:00'::TIMESTAMPTZ, '8a502b694fe1a63f70230c671309d13e26098bac7e53a43a0f0b6a36e944d1bc'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (206::BIGINT, 'Es súper vaga... Esos resúmenes que hace solo le pueden gustar a gente vaga que lo que quiere es pasar el curso y no le interesa aprender. No explica nada. Solo medio lee entre dientes el resumen ese. Califica muy suave, pero solo lo hace porque es muy mala.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-18T00:00:00+00:00'::TIMESTAMPTZ, '133f42637b8f3b473988e74253c6818356648fbd3c497a69f852c22ac81b3b33'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-14T00:00:00+00:00'::TIMESTAMPTZ, '78b82aab5171a8909934a7040887c6f1e612625986aefdc0e03dacdb779f03fe'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Buenísima profe. Da resúmenes del los capítulos del libro que traen básicamente la teoría del examen. Deja muchísima práctica y resuelve todo lo que deja...muy pura vida y califica bien suave. Recomendadisima'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-08T00:00:00+00:00'::TIMESTAMPTZ, '70c7a3c2262db18f7323ba797c84d2ee88e67d9776bc806ecc0f3ad5dd39969f'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (206::BIGINT, 'Recomendada para Fisica I explica completamente la teoria del tema y despues hace ejercicios en la clase, los resuelve todos y son muy parecidos a los del examen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'c35279c54763ddf06e06a33deec11a892f6440191d95b05aa964734a37670a8f'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Es muy buena profesora para Física I, respeto los comentarios de cualquiera, pero tuve compañer@s que no se esforzaban nada en el curso, lo pierden y al final dicen que ella no explica lo suficiente. Es mentira, solo que hay que prestar atención.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-22T00:00:00+00:00'::TIMESTAMPTZ, '79eddcf36409ad6e8f2dccd1ed2bdbf2586626687546096792f1225d9332737b'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, '7e954f99d38a30dbf73e4bc9d40ab9e69d71ff18ef784245971883c7f703a023'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'No explica con claridad, exámenes cortos no muy fáciles, lo único bueno es que califica suave.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-17T00:00:00+00:00'::TIMESTAMPTZ, '1a7f5c824f15fc4d741d1f1ffc39d18fcc5fd14da4fa6771dd318a94bb8b48fd'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Una Profesora desinteresada, no explica bien, si aprendes bueno, si no también. No recomiendo llevar el curso con ella. Es la profesora que cree que sabes todo y aprendes rápido, mientras analizas un tema, ella esta en el otro, avanza muy rápido y sin claridad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'ddf2636321ba37761348d0f8930e89337ad00bcb898d36fc9fb2a5835143de8a'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'La recomiendo, pero solo si no hay mucha gente en el aula, pues habla muy bajito. En cuanto a lo demás es una profesora regular que califica justo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '794d69961cb60adc666d1b85391964b4766f467fbecc85dc5720800e47f43f52'::TEXT, ARRAY[630]::BIGINT[]),
    (206::BIGINT, 'Es muy divertida y se rie de los estudiantes cuando estan mamando, cae muy bien y es buena profe, eso si informes a mano'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'da8260e4859e586e93c3274aae9c14e4d2b301e5f8efb11e507132181e4c4b0b'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'ac9b7679b86f373ce808f5d666f16534fdb77a57cb853f6c4265f51dda45c22f'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b373eea5a68ccaca29652f497e3504d686bf9a4a055bc4c94dfeb3b5abb8eeae'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Aclara dudas en clase y consulta. Siempre muy pendiente de sus estudiantes y no califica tan duro en los exámenes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '8b06b1707c57de025a00ebddb2f316050e73c163fb41c5aebeca34dfa2f32b99'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'fc3cd3d012d9979735b2b1e430b828ec33c7ef23bce43800c4245cb8211c9874'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Al momento de dar la clase habla muy bajo y ademas escribe muy pequeño, por lo que si se lleva por primera vez física, no es recomendada'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '88b35f2ee80b07ef900ae3a4a955ff30150aeced163c78d56750cf980c989176'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'califica muy bien pero para llevar física por primera vez no es recomendable porque casi no explica ademas de que escribe demasiado pequeño y habla muy bajo para una clase de 71 personas :S! Los deja morir con practicas super difíciles nada que ver con las clases que da :S'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a413f7b6492876303fa7218e64394023a23a9a4a3edde3c0eeb14433b0f6595e'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Es una tejota, ayuda con los quices, para llevar el curso por segunda vez es muy buena porque no se pone en rodeos sino de una vez a lo que vinimos, escribe mucho en la pizarra, no evalua tan rudo, dura toda la vida revisando'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '9a069f9df540ac373f0a80b9719bac5626175bed51bf26cee741ff01d4248d50'::TEXT, ARRAY[604]::BIGINT[]),
    (206::BIGINT, 'Muy buena como persona y como profe no esta mal'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '8a8c261d6a2cf5e57d8afbd24b2eb645cd3216a5b14dd47e4395b51025fd3bae'::TEXT, ARRAY[604, 922]::BIGINT[]),
    (206::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c0ec53efbc9682bdc796fecbd07b0043019616e0dc407e6225fa8b3cb39bdb8a'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (206::BIGINT, 'Como persona es chiva y como profe hace que el curso no sea tan complicado, explica masomenos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'e134e501859c2d79a208f1ebc9c2e6aa3d7f0bb12ddce80794d28a424382022c'::TEXT, ARRAY[607]::BIGINT[]),
    (206::BIGINT, 'Excelente profesora'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'b11e330066b25e36ab2ab1cb3b5113988db3eb4f81f2df528e011f9af134a9de'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
